SELECT
COUNT(*)
FROM T_ENC_INFO
WHERE 1 = 1

    AND TARGET_GB_CD = #{targetGbCd}


    AND TARGET_VAL = #{targetVal}

SELECT T.ROW_NUM AS ROW_NUM ,T.* FROM ( SELECT ROW_NUMBER() OVER(ORDER BY TARGET_GB_CD, TARGET_VAL) ROW_NUM ,TARGET_GB_CD ,TARGET_VAL ,ENC_KEY ,SALT_VAL ,ENC_STS_CD ,REG_USER_ID ,REG_DT ,LAST_MOD_USER_ID ,LAST_MOD_DT FROM T_ENC_INFO WHERE 1 = 1
AND TARGET_GB_CD = #{targetGbCd}
AND TARGET_VAL = #{targetVal}
ORDER BY TARGET_GB_CD, TARGET_VAL ) T
WHERE T.ROW_NUM BETWEEN #{startIndex} AND #{endIndex}
